{
  "run": {
    "runId": "run_7f3a91",
    "agent": "refund-bot@2.3.1",
    "outcome": {
      "id": "refund_order_1188",
      "description": "Refund order 1188 in full to the original payment method"
    },
    "before": {
      "orders": {
        "1188": {
          "status": "paid",
          "total": {
            "amountMinor": 118800,
            "currency": "USD"
          },
          "refundId": null
        }
      },
      "customers": {
        "c_44": {
          "email": "customer@example.com",
          "tier": "pro"
        }
      },
      "ledger": {
        "payouts": {
          "amountMinor": 4820000,
          "currency": "USD"
        }
      }
    },
    "after": {
      "orders": {
        "1188": {
          "status": "refunded",
          "total": {
            "amountMinor": 118800,
            "currency": "USD"
          },
          "refundId": "re_9021"
        }
      },
      "customers": {
        "c_44": {
          "email": "customer@example.com",
          "tier": "free"
        }
      },
      "ledger": {
        "payouts": {
          "amountMinor": 4701200,
          "currency": "USD"
        }
      }
    },
    "preconditions": [
      {
        "op": "equals",
        "path": "orders.1188.status",
        "value": "paid"
      }
    ],
    "postconditions": [
      {
        "op": "equals",
        "path": "orders.1188.status",
        "value": "refunded"
      },
      {
        "op": "exists",
        "path": "orders.1188.refundId"
      }
    ],
    "expectedChanges": [
      "ledger.payouts"
    ],
    "declaredEffects": [
      {
        "kind": "refund",
        "target": "psp.example"
      }
    ],
    "observedEffects": [
      {
        "kind": "refund",
        "target": "psp.example",
        "amountMinor": 118800,
        "currency": "USD"
      },
      {
        "kind": "email",
        "target": "customer@example.com",
        "description": "Refund confirmation"
      }
    ],
    "policies": [
      {
        "id": "no-tier-edits",
        "kind": "forbid_change",
        "path": "customers.**.tier"
      }
    ]
  }
}

